import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] input = scanner.nextLine().split(" ");
        int p = Integer.parseInt(input[0]);
        int k = Integer.parseInt(input[1]);
        long mmod = (long) Math.pow(10, 9) + 7;

        if (k == 0) {
            System.out.println(modPow(p, p - 1, mmod));
        } else if (k == 1) {
            System.out.println(modPow(p, p, mmod));
        } else {
            int i;
            long x = 1;
            for (i = 1; i <= p; i++) {
                x = (x * k) % p;
                if (x == 1) {
                    break;
                }
            }
            System.out.println(modPow(p, (p - 1) / i, mmod));
        }
        scanner.close();
    }

    private static long modPow(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}
